/* the agent's searches as a trail: each query with what came back, each page with whether it was read, skimmed or skipped and
   why; once done it folds to one line, and the answer under it points back at its pages */
.dm-wsx{padding:6px;display:flex;flex-direction:column;font-size:13px}
.dm-wsx-h{display:flex;align-items:center;gap:10px;width:100%;padding:var(--dm-s-2) 10px;border-radius:var(--dm-r-in);text-align:left;font-size:13.5px;transition:background var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.dm-wsx-h:hover{background:var(--dm-row)}}
.dm-wsx-ic{width:16px;height:16px;flex:none;display:grid;place-items:center;color:var(--dm-fg2)}
.dm-wsx-ic .dm-spin{width:11px;height:11px}
.dm-wsx-st{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-wsx-h>.dm-i{color:var(--dm-muted);transition:transform .32s var(--dm-ease)}
.dm-wsx-h[aria-expanded="false"]>.dm-i{transform:rotate(-90deg)}
/* the sites it went to, as a small stack of initials, the rest counted */
.dm-wsx-marks{display:flex;align-items:center}
.dm-wsx-marks span{width:20px;height:20px;border-radius:50%;display:grid;place-items:center;margin-left:-5px;background:var(--dm-chip);color:var(--dm-fg2);font-size:10.5px;font-weight:500;box-shadow:0 0 0 2px var(--dm-surface);transition:background .2s,color .2s}
.dm-wsx-marks span.dm-n{background:var(--dm-surface);color:var(--dm-muted);box-shadow:0 0 0 2px var(--dm-surface),inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:10px}
.dm-wsx-marks span.dm-hl{background:var(--dm-fg2);color:var(--dm-surface)}
.dm-wsx-list{display:flex;flex-direction:column;gap:2px;padding:2px 0 var(--dm-s-1)}
.dm-wsx-q{display:flex;flex-direction:column}
.dm-wsx-qh{display:grid;grid-template-columns:16px minmax(0,1fr) auto auto 12px;align-items:center;column-gap:var(--dm-s-2);width:100%;padding:6px 10px;border-radius:calc(10px * var(--dm-rk));text-align:left;transition:background var(--dm-t-fast)}
.dm-wsx-q.dm-hl>.dm-wsx-qh{background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.dm-wsx-qh:hover{background:var(--dm-row)}}
.dm-wsx-qh>.dm-i:first-child{color:var(--dm-muted)}
.dm-wsx-qh .dm-t{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--dm-fg)}
.dm-wsx-qh .dm-n,.dm-wsx-qh .dm-tm{font-size:12px;color:var(--dm-muted);white-space:nowrap}
.dm-wsx-qh .dm-n.dm-none{color:var(--dm-warn)}
.dm-wsx-qh>.dm-i:last-child{color:var(--dm-muted);transition:transform .32s var(--dm-ease)}
.dm-wsx-qh[aria-expanded="true"]>.dm-i:last-child{transform:rotate(90deg)}
.dm-wsx-qh[aria-expanded="false"].dm-empty>.dm-i:last-child{visibility:hidden}
.dm-wsx-rw{display:flex;align-items:center;gap:6px;padding:0 10px 2px 34px;font-size:12px;color:var(--dm-muted)}
.dm-wsx-rs{list-style:none;margin:0;padding:2px 0 var(--dm-s-1) 26px;display:flex;flex-direction:column;gap:2px}
.dm-wsx-r{display:grid;grid-template-columns:20px minmax(0,1fr) auto;column-gap:var(--dm-s-2);align-items:center;padding:5px var(--dm-s-2);border-radius:calc(9px * var(--dm-rk));transition:background var(--dm-t-fast);cursor:default}
.dm-wsx-r.dm-hl{background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.dm-wsx-r:hover{background:var(--dm-row)}}
.dm-wsx-r:focus-visible{outline-offset:-2px}
.dm-wsx-fav{width:20px;height:20px;border-radius:calc(6px * var(--dm-rk));display:grid;place-items:center;background:var(--dm-chip);color:var(--dm-fg2);font-size:10.5px;font-weight:500}
.dm-wsx-r .dm-tx{display:flex;flex-direction:column;min-width:0;line-height:1.35}
.dm-wsx-r .dm-t{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:12.5px;color:var(--dm-fg)}
.dm-wsx-r .dm-d{font-size:11.5px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dm-wsx-r.dm-skip .dm-t{color:var(--dm-muted)}
.dm-wsx-r .dm-tag .dm-spin{width:9px;height:9px}
.dm-wsx-ans{padding:var(--dm-s-2) 10px 6px;font-size:13.5px;line-height:1.6;color:var(--dm-fg)}
.dm-wsx-ans:empty{display:none}
.dm-wsx-cite{display:inline-grid;place-items:center;min-width:18px;height:17px;padding:0 4px;margin:0 1px;border-radius:calc(5px * var(--dm-rk));background:var(--dm-chip);color:var(--dm-fg2);font-size:11px;font-weight:500;vertical-align:1px;transition:background var(--dm-t-fast),color var(--dm-t-fast)}
.dm-wsx-cite.dm-on{background:var(--dm-fg2);color:var(--dm-surface)}
@media (hover:hover) and (pointer:fine){.dm-wsx-cite:hover{background:var(--dm-fg2);color:var(--dm-surface)}}
.dm-wsx-sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}

